 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if current_user not in ('postgres', 'service_role') then
    raise exception using errcode = '42501', message = 'TORNEOS_PROJECTION_IMMUTABLE';
  end if;
  return coalesce(new, old);
end;
